pub async fn fetch_or_insert<K, V, F>(&self, key: K, loader: F) -> Result<V> {
    if let Some(value) = self.fresh(&key).await? { return Ok(value); }
    self.singleflight.run(key, async move { loader().await }).await
}

export class RequestCoalescer<K, V> {
  private inflight = new Map<K, Promise<V>>();
  run(key: K, factory: () => Promise<V>): Promise<V> {
    return this.inflight.get(key) ?? this.track(key, factory());
  }
}
